def find_max_form(strs, m, n):
    cost = [(s.count("0"), s.count("1")) for s in strs]

    def f(i, z, o):            # most of the first i strings within z zeros, o ones
        if i == 0:
            return 0
        best = f(i - 1, z, o)
        cz, co = cost[i - 1]
        if cz <= z and co <= o:
            best = max(best, 1 + f(i - 1, z - cz, o - co))
        return best
    return f(len(strs), m, n)

